  // Validate top-level structure
  if (input === null || Array.isArray(input) || typeof input !== 'object') {
    return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
  }

  const keys = Object.keys(input);
  if (keys.length !== 1 || keys[0] !== 'rows') {
    return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
  }

  const rows = input.rows;
  if (!Array.isArray(rows)) {
    return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
  }

  if (rows.length > 200) {
    return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
  }

  const validUnits = ['TOKENS', 'MILLISECONDS', 'CHECKS'];
  const seenIds = new Set();

  // Validate each row
  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];

    if (row === null || Array.isArray(row) || typeof row !== 'object') {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    const rowKeys = Object.keys(row);
    if (rowKeys.length !== 5 || !rowKeys.every(k => ['id', 'label', 'off', 'on', 'unit'].includes(k))) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // Validate id
    const id = row.id;
    if (typeof id !== 'string' || id.length < 1 || id.length > 128) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    if (seenIds.has(id)) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }
    seenIds.add(id);

    // Validate label
    const label = row.label;
    if (typeof label !== 'string' || label.length < 1 || label.length > 128) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // Validate unit
    const unit = row.unit;
    if (!validUnits.includes(unit)) {
      return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
    }

    // Validate off
    const off = row.off;
    if (off !== null) {
      if (typeof off !== 'number' || !Number.isFinite(off) || off < 0 || Object.is(off, -0)) {
        return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
      }
      if (unit === 'TOKENS' || unit === 'CHECKS') {
        if (!Number.isInteger(off) || off < 0 || off > Number.MAX_SAFE_INTEGER) {
          return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
        }
      } else if (off > Number.MAX_SAFE_INTEGER) {
        return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
      }
    }

    // Validate on
    const on = row.on;
    if (on !== null) {
      if (typeof on !== 'number' || !Number.isFinite(on) || on < 0 || Object.is(on, -0)) {
        return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
      }
      if (unit === 'TOKENS' || unit === 'CHECKS') {
        if (!Number.isInteger(on) || on < 0 || on > Number.MAX_SAFE_INTEGER) {
          return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
        }
      } else if (on > Number.MAX_SAFE_INTEGER) {
        return { status: 'REFUSED', reason: 'INVALID_INPUT', authorizing: false };
      }
    }
  }

  // Process rows
  const processedRows = [];
  let knownPairs = 0;
  let unknownPairs = 0;

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const off = row.off;
    const on = row.on;

    const delta = (off !== null && on !== null) ? on - off : null;

    let relativeChangePercent = null;
    if (off !== null && on !== null && off > 0) {
      const result = ((on - off) / off) * 100;
      if (Number.isFinite(result)) {
        relativeChangePercent = result;
      }
    }

    processedRows.push({
      id: row.id,
      label: row.label,
      off: off,
      on: on,
      unit: row.unit,
      delta: delta,
      relativeChangePercent: relativeChangePercent
    });

    if (off !== null && on !== null) {
      knownPairs++;
    } else {
      unknownPairs++;
    }
  }

  return {
    schemaVersion: 1,
    status: 'READY',
    rows: processedRows,
    summary: {
      total: rows.length,
      knownPairs: knownPairs,
      unknownPairs: unknownPairs
    },
    authorizing: false
  };
}"},{"notes":["No validation of actual model correctness, hardware accuracy, permissions, or execution evidence. Input must be ordinary JSON with exact structure as specified. All validation is structural and type-based only."]}

